import { useState, useEffect } from "react";

export default function AdminPage() {
  const [orders, setOrders] = useState([]);
  const [activeTab, setActiveTab] = useState("status");
  const [menu, setMenu] = useState([]);
  const [newItem, setNewItem] = useState({ category: "", name: "", price: "" });
  const [theme, setTheme] = useState("dark");

  useEffect(() => {
    const savedOrders = JSON.parse(localStorage.getItem("allOrders") || "[]");
    const savedMenu = JSON.parse(localStorage.getItem("menuData") || "[]");
    const savedTheme = localStorage.getItem("theme") || "dark";
    setOrders(savedOrders);
    setMenu(savedMenu);
    setTheme(savedTheme);
  }, []);

  useEffect(() => {
    localStorage.setItem("menuData", JSON.stringify(menu));
    localStorage.setItem("theme", theme);
    document.body.className = theme;
  }, [menu, theme]);

  const updateOrderStatus = (index, nextStatus) => {
    const updated = [...orders];
    updated[index].status = nextStatus;
    setOrders(updated);
    localStorage.setItem("allOrders", JSON.stringify(updated));
    if (nextStatus === "Fertig") {
      localStorage.removeItem("currentOrder");
    } else {
      localStorage.setItem("currentOrder", JSON.stringify(updated[index]));
    }
  };

  const updateAvailability = (catIndex, itemIndex) => {
    const updated = [...menu];
    updated[catIndex].items[itemIndex].available = !updated[catIndex].items[itemIndex].available;
    setMenu(updated);
  };

  const deleteItem = (catIndex, itemIndex) => {
    const updated = [...menu];
    updated[catIndex].items.splice(itemIndex, 1);
    setMenu(updated);
  };

  const addItem = () => {
    if (!newItem.category || !newItem.name || !newItem.price) return;
    const item = {
      name: newItem.name,
      price: parseFloat(newItem.price),
      available: true,
    };
    const updated = [...menu];
    const cat = updated.find(c => c.category === newItem.category);
    if (cat) {
      cat.items.push(item);
    } else {
      updated.push({ category: newItem.category, items: [item] });
    }
    setMenu(updated);
    setNewItem({ category: "", name: "", price: "" });
  };

  return (
    <div className="min-h-screen p-4">
      <div className="flex gap-4 mb-6">
        <button onClick={() => setActiveTab("status")} className="px-4 py-2 bg-blue-600 rounded">
          Bestellungen
        </button>
        <button onClick={() => setActiveTab("menu")} className="px-4 py-2 bg-blue-600 rounded">
          Speisekarte bearbeiten
        </button>
        <button onClick={() => setActiveTab("design")} className="px-4 py-2 bg-blue-600 rounded">
          Design ändern
        </button>
      </div>

      {activeTab === "status" && (
        <div>
          <h2 className="text-xl font-bold mb-4">Bestellungen</h2>
          {orders.length === 0 ? (
            <p>Keine Bestellungen vorhanden.</p>
          ) : (
            orders.map((order, index) => (
              <div key={index} className="border p-3 mb-2 rounded bg-gray-800 text-white">
                <p className="mb-1 font-semibold">Tisch: {order.tableNumber}</p>
                <ul className="mb-2 list-disc pl-4">
                  {order.items.map((item, i) => (
                    <li key={i}>
                      {item.name} – {typeof item.price === "number" ? item.price.toFixed(2) : "?"} €
                    </li>
                  ))}
                </ul>
                <p className="mb-2">Status: {order.status}</p>
                {order.status === "Ausstehend" && (
                  <button
                    onClick={() => updateOrderStatus(index, "In Zubereitung")}
                    className="bg-yellow-600 hover:bg-yellow-700 px-3 py-1 rounded mr-2"
                  >
                    In Zubereitung
                  </button>
                )}
                {order.status === "In Zubereitung" && (
                  <button
                    onClick={() => updateOrderStatus(index, "Fertig")}
                    className="bg-green-600 hover:bg-green-700 px-3 py-1 rounded"
                  >
                    Fertig
                  </button>
                )}
              </div>
            ))
          )}
        </div>
      )}

      {activeTab === "menu" && (
        <div>
          <h2 className="text-xl font-bold mb-4">Speisekarte bearbeiten</h2>
          {menu.map((cat, catIndex) => (
            <div key={catIndex} className="mb-6">
              <h3 className="text-lg font-semibold">{cat.category}</h3>
              {cat.items.map((item, itemIndex) => (
                <div key={itemIndex} className="flex items-center gap-2 mb-1 text-white">
                  <span>
                    {item.name} – {typeof item.price === "number" ? item.price.toFixed(2) : "?"} €
                  </span>
                  <label className="flex items-center">
                    <input
                      type="checkbox"
                      checked={item.available}
                      onChange={() => updateAvailability(catIndex, itemIndex)}
                      className="ml-2"
                    />
                    <span className="ml-1 text-sm">verfügbar</span>
                  </label>
                  <button
                    onClick={() => deleteItem(catIndex, itemIndex)}
                    className="ml-auto bg-red-600 hover:bg-red-700 px-2 py-1 rounded text-sm"
                  >
                    Löschen
                  </button>
                </div>
              ))}
            </div>
          ))}
          <div className="mt-6">
            <h3 className="text-lg font-semibold mb-2">Neuen Artikel hinzufügen</h3>
            <div className="flex flex-col md:flex-row gap-2">
              <input
                className="p-2 rounded text-black"
                placeholder="Kategorie"
                value={newItem.category}
                onChange={(e) => setNewItem({ ...newItem, category: e.target.value })}
              />
              <input
                className="p-2 rounded text-black"
                placeholder="Name"
                value={newItem.name}
                onChange={(e) => setNewItem({ ...newItem, name: e.target.value })}
              />
              <input
                className="p-2 rounded text-black"
                placeholder="Preis"
                type="number"
                value={newItem.price}
                onChange={(e) => setNewItem({ ...newItem, price: e.target.value })}
              />
              <button
                onClick={addItem}
                className="bg-green-600 hover:bg-green-700 px-4 py-2 rounded text-white"
              >
                Hinzufügen
              </button>
            </div>
          </div>
        </div>
      )}

      {activeTab === "design" && (
        <div>
          <h2 className="text-xl font-bold mb-4">Design ändern</h2>
          <div className="flex gap-3">
            {["dark", "light", "blue", "white", "techy"].map((t) => (
              <button
                key={t}
                onClick={() => setTheme(t)}
                className={`px-4 py-2 rounded ${theme === t ? "bg-green-600" : "bg-gray-700"}`}
              >
                {t}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}
